{
 "app_name": "amazon",
 "api_name": "show_orders",
 "path": "/amazon/orders",
 "method": "GET",
 "description": "Show or search your past orders",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from amazon app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "Search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 20"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the orders by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page. If both query and sort_by are not given, null, or empty, sort_by will default to -created_at.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "order_id": 1,
    "address_id": 1,
    "payment_card_id": 1,
    "tax": 0.0,
    "delivery_fee": 0.0,
    "gift_wrap_fee": 0.0,
    "discount": 0.0,
    "created_at": "2019-01-01T00:00:00",
    "address_text": "string",
    "payment_card_digits": "string",
    "paid_amount": 0.0,
    "order_items": [
     {
      "product_id": 1,
      "product_name": "string",
      "product_review_id": 1,
      "ordered_quantity": 1,
      "returned_quantity": 1,
      "gift_wrap_quantity": 1,
      "price": 0.0,
      "expected_delivery_at": "2019-01-01T00:00:00",
      "delivered_at": "2019-01-01T00:00:00"
     }
    ]
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
